package com.example.leavemanagement.policy.api;
import com.example.leavemanagement.policy.application.*; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/admin/holidays") public class AdminHolidayController {private final HolidayAdministrationService service;public AdminHolidayController(HolidayAdministrationService s){service=s;} @GetMapping public List<HolidayAdministrationService.View> list(@RequestParam LocalDate from,@RequestParam LocalDate to){return service.list(from,to);} @PostMapping @ResponseStatus(HttpStatus.CREATED) public HolidayAdministrationService.View create(@Valid @RequestBody Create c){return service.create(new HolidayAdministrationService.Create(c.date(),c.name(),c.active()));} @PatchMapping("/{id}") public HolidayAdministrationService.View update(@PathVariable UUID id,@Valid @RequestBody Update c){return service.update(id,new HolidayAdministrationService.Update(c.date(),c.name(),c.active(),c.expectedVersion()));} public record Create(@NotNull LocalDate date,@NotBlank @Size(max=160)String name,boolean active){} public record Update(@NotNull LocalDate date,@NotBlank @Size(max=160)String name,boolean active,@NotNull @Min(0)Long expectedVersion){} }
